  if (r.archived && !S.ui['qarch-' + r.lid]) return `${pageA(esc(r.learner), r.id, '', [['Assessment Records', 'q-records'], [r.id]])}<div class="card" style="max-width:560px"><h2>${ic('lock')} Archived learner — state your purpose</h2><p class="small">Access to archived records is logged with your purpose.</p><div class="field"><label for="qa-p">Purpose of access</label><select class="select" id="qa-p"><option>Awarding-body audit</option><option>Regulatory compliance</option><option>Internal quality assurance</option></select></div><button class="btn btn-primary" data-act="qArch" data-l="${r.lid}" data-id="${r.id}">Open record</button></div>`;
