    left = `<section class="card"><h2>PD outcomes</h2><ul class="list small">${items.map(i => `<li class="li"><div class="li-b"><span class="code">${esc(i[0])}</span><span>${esc(i[1])}</span></div>${chip(i[2], /Met|Achieved/.test(i[2]) && !/Not/.test(i[2]) ? 'green' : 'amber')}</li>`).join('')}</ul></section>`;
    centre = `<section class="card"><h2>Assessment decision</h2><p class="small">Recorded by <strong>${esc(r.assessor)}</strong> · ${fdt(r.markedAt)} ${ic('lock', 12)}</p></section>`;
