/* ---------- 6.3 Findings ---------- */
const F_CATS = ['Decision supported', 'Decision not supported by evidence', 'Feedback quality', 'Mapping / criteria issue', 'Procedural (dates, verification)', 'Observation recording', 'Other'];
const F_ACTIONS = ['None', 'Assessor to review', 'Refer to Academic Admin', 'Consider Data Correction'];
const F_STATUS = ['Open', 'Acknowledged', 'Closed'];
// G6.9: conflict — the IQA marked it, or is a Teacher or Assessor on that batch (different batches are fine)
const iqaConflict = (r, me = ADMIN.me.name) => { if (!r) return false; if (r.assessor === me) return 'You marked this work'; const b = ADMIN.batches.find(x => x.code === r.batch || x.label === r.batch); if (b && b.teachers.includes(me)) return 'You are a Teacher on this batch'; const role = b && typeof chRoleOn === 'function' && chRoleOn(b, me); if (role) return `You are the ${role} on this batch`; if (b && b.assessors.includes(me)) return 'You are an Assessor on this batch'; return false; }; // CH-17: any of the three allocations
function findingCard(f) { return `<div class="iqa-finding"><div class="if-h"><span class="iqa-badge">${ic('shield', 13)}IQA finding</span><span class="xs mono">${f.id}</span> ${chip(f.status || 'Open', { Open: 'amber', Acknowledged: 'blue', Closed: 'grey' }[f.status || 'Open'])}</div><p class="small">${esc(f.text)}</p><p class="xs muted">${esc(f.cat || '—')} · ${esc(f.by)} · ${fd(f.at)}${f.edits && f.edits.length ? ' · edited' : ''}</p><button class="linklike xs" data-go="q-finding" data-id="${f.id}">Open finding</button></div>`; }
ACT.qRecord = el => {
  const r = recById(el.dataset.id), cf = iqaConflict(r); if (cf) { toast(cf + ' — another IQA must record findings.', 'err'); return; }
  const d = STORE.iqa.drafts[r.id] = STORE.iqa.drafts[r.id] || { q: '', cat: '', text: '', action: 'Assessor to review' };
  const qs = r.kind === 'sub' ? r.crit.map((c, k) => `Q${k + 1} · ${c}`) : r.crit;
  openModal({ title: 'Record finding', sub: `${esc(r.id)} · ${esc(r.learner)} · ${esc(r.title)}${r.round !== '—' ? ' (' + r.round + ')' : ''}`, size: 'lg', body: `<div class="note b-blue">${ic('info')}<div class="small"><strong>This finding is visible to the marking assessor and administrators only. It does not change the mark.</strong> Corrections go through a Data Correction Request raised by the assessor or an administrator.</div></div>
    <div class="field"><label for="qf-q">Specific question or criterion (optional)</label><select class="select" id="qf-q" data-oninput="qfDraft" data-onchange="qfDraft" data-id="${r.id}" data-k="q"><option value="">Whole record</option>${qs.map(x => `<option ${d.q === x ? 'selected' : ''}>${esc(x)}</option>`).join('')}</select></div>
    <div class="field"><label for="qf-c">Category</label><select class="select" id="qf-c" data-onchange="qfDraft" data-id="${r.id}" data-k="cat"><option value="">Choose a category…</option>${F_CATS.map(c => `<option ${d.cat === c ? 'selected' : ''}>${c}</option>`).join('')}</select></div>
    <div class="field"><label for="qf-t">Finding (required)</label><textarea class="textarea" id="qf-t" rows="5" data-oninput="qfDraft" data-id="${r.id}" data-k="text">${esc(d.text)}</textarea></div>
    <div class="field"><label for="qf-a">Action recommended</label><select class="select" id="qf-a" data-onchange="qfDraft" data-id="${r.id}" data-k="action">${F_ACTIONS.map(c => `<option ${d.action === c ? 'selected' : ''}>${c}</option>`).join('')}</select></div><p class="xs muted">Drafts are kept if your session times out.</p>`,
    actions: [{ label: 'Cancel' }, { label: 'Save finding', cls: 'btn-primary', fn: () => {
      if (!d.text.trim()) { fieldErr('#qf-t', 'Write the finding'); return false; } if (!d.cat) { fieldErr('#qf-c', 'Choose a category'); return false; }
      const id = 'IQA-' + (400 + ADMIN.iqa.length), f = { id, text: d.text.trim(), by: ADMIN.me.name, at: now().toISOString(), sub: `${r.learner} · ${r.title.replace(/^L\d /, '').split(' —')[0]} (${r.round === '—' ? KIND_LBL[r.kind] : r.round})`, assessor: r.assessor, rec: r.id, q: d.q, cat: d.cat, action: d.action, status: 'Open', edits: [] };
      ADMIN.iqa.unshift(f); delete STORE.iqa.drafts[r.id]; iqaLog(r.id, 'Finding recorded', id, d.cat);
      if (STORE.tas) STORE.tas.notifs.unshift({ id: 'tn' + Date.now(), t: 'IQA finding recorded on my work', b: `${id} · ${r.learner} — ${r.title}`, at: now().toISOString(), go: 't-iqa', unread: true, cat: 'Marking' });
      render(); toast(`Finding ${id} saved. ${r.assessor} has been notified${isFormer(r.assessor) ? ' (former assessor — sees findings while still an active user)' : ''}.`);
    } }] });
};
INP.qfDraft = el => { const d = STORE.iqa.drafts[el.dataset.id]; if (d) d[el.dataset.k] = el.value; };
const fRec = f => f.rec ? recById(f.rec) : recForFinding(f);
SCREENS['q-findings'] = () => { const rows = ADMIN.iqa.map(f => { const r = fRec(f); return { ...f, r, learner: r ? r.learner : f.sub.split(' · ')[0], programme: r ? r.pk : '—', unit: r ? r.unit : '—', round: r ? r.round : '—' }; });
  return `${pageA('IQA Findings', 'Visible to the marking assessor and administrators only — never to learners. Findings never change marks.', exportMenu('IQA findings'))}${dt({ id: 'qfind', name: 'IQA findings', rows, pageSize: 12, search: f => f.id + f.text + f.learner + f.assessor, filters: [{ k: 'as', l: 'Assessor', get: f => f.assessor }, { k: 'pg', l: 'Programme', get: f => f.programme }, { k: 'un', l: 'Unit', get: f => f.unit }, { k: 'c', l: 'Category', get: f => f.cat || '—', opts: F_CATS }, { k: 'by', l: 'Author', get: f => f.by }, { k: 's', l: 'Status', get: f => f.status || 'Open', opts: F_STATUS }],
    cols: [{ k: 'id', l: 'Finding', h: f => `<a href="#q-finding.${f.id}" data-go="q-finding" data-id="${f.id}" class="mono strong">${f.id}</a>` }, { k: 'rec', l: 'Record', h: f => f.r ? `<a href="#q-record.${f.r.id}" data-go="q-record" data-id="${f.r.id}" class="mono small">${f.r.id}</a>` : '<span class="muted small">Sample note</span>', v: f => f.rec || '' }, { k: 'learner', l: 'Learner' }, { k: 'programme', l: 'Programme' }, { k: 'unit', l: 'Unit' }, { k: 'assessor', l: 'Assessor' }, { k: 'round', l: 'Round', h: f => `<span class="code">${f.round}</span>` }, { k: 'cat', l: 'Category', h: f => `<span class="small">${esc(f.cat || '—')}</span>` }, { k: 'by', l: 'Author' }, { k: 'at', l: 'Date', h: f => fd(f.at), s: f => f.at }, { k: 'action', l: 'Action', h: f => `<span class="small">${esc(f.action || '—')}</span>` }, { k: 'status', l: 'Status', h: f => chip(f.status || 'Open', { Open: 'amber', Acknowledged: 'blue', Closed: 'grey' }[f.status || 'Open']), v: f => f.status || 'Open' }] })}`; };
SCREENS['q-finding'] = (p) => {
  const f = ADMIN.iqa.find(x => x.id === p.id); if (!f) return notFound();
  const r = fRec(f), mine = f.by === ADMIN.me.name, editable = mine && -daysTo(f.at) * 24 <= 24, corr = r && STORE.iqa.corr[r.id];
  return `${pageA('Finding ' + f.id, `${esc(f.cat || '—')} · ${esc(f.by)} · ${fdt(f.at)}`, chip(f.status || 'Open'), [['IQA Findings', 'q-findings'], [f.id]])}
  <div class="grid-2"><section class="card">${findingCard(f).replace(/<button class="linklike xs"[^>]*>Open finding<\/button>/, '')}<dl class="kv"><dt>Question / criterion</dt><dd>${esc(f.q || 'Whole record')}</dd><dt>Action recommended</dt><dd>${esc(f.action || '—')}</dd><dt>Assessor</dt><dd>${esc(f.assessor)}${isFormer(f.assessor) ? ` <span class="typebadge">Former</span>` : ''}</dd><dt>Visible to</dt><dd class="small">The marking assessor and administrators only</dd></dl>
    <div class="row">${editable ? `<button class="btn btn-sm" data-act="qEditF" data-id="${f.id}">Edit</button>` : `<span class="xs muted">${mine ? 'Editing window has closed.' : 'Findings by another IQA are read-only.'} Findings can't be deleted.</span>`}</div>
    ${f.edits && f.edits.length ? `<h3 class="small">Version history</h3><ol class="tl">${f.edits.map((e, k) => `<li class="done"><span class="tl-d">v${k + 1}</span><div class="small"><span class="strike">${esc(e[1])}</span><div class="xs muted">${esc(e[0])} · ${fdt(e[2])}</div></div></li>`).join('')}</ol>` : ''}</section>
  <section class="card"><h2>Linked record</h2>${r ? `<dl class="kv"><dt>Record</dt><dd><button class="linklike mono" data-go="q-record" data-id="${r.id}">${r.id}</button></dd><dt>Learner</dt><dd>${esc(r.learner)}</dd><dt>Work</dt><dd>${esc(r.title)} · ${r.round}</dd><dt>Exit</dt><dd>${r.exit}</dd></dl>${corr ? `<div class="note b-grey">${ic('refresh')}<div class="small"><strong>Correction applied:</strong> <span class="strike">${esc(corr.from)}</span> → ${esc(corr.to)} · ${fd(corr.at)}</div></div>` : ''}` : `<p class="small">${esc(f.sub)}</p>`}</section></div>${auditPanel(a => a.entity === f.id || a.after === f.id || (r && a.entity === r.id))}`;
};
ACT.qEditF = el => { const f = ADMIN.iqa.find(x => x.id === el.dataset.id); reasonDlg({ title: 'Edit finding ' + f.id, ok: 'Save new version', label: 'Reason for the edit (required)', extra: `<div class="field"><label for="qe-t">Finding</label><textarea class="textarea" id="qe-t" rows="4">${esc(f.text)}</textarea></div>`, onOk: r => { (f.edits = f.edits || []).push([ADMIN.me.name, f.text, now().toISOString()]); f.text = $('#qe-t').value.trim() || f.text; iqaLog(f.id, 'Finding edited', 'v' + (f.edits.length + 1), r); render(); toast('Finding updated — the previous version is kept.'); } }); };

/* ---------- 6.2 Sample sets [NEW] ---------- */
const S_TONE = { Open: 'blue', Finalised: 'grey', Exported: 'green' };
SCREENS['q-sets'] = () => `${pageA('Sample Sets', 'Every item is chosen by you — no automated or random population.', `<button class="btn btn-primary" data-act="qNewSet">${ic('plus', 15)}New sample set</button>`)}${dt({ id: 'qsets', name: 'Sample sets', rows: STORE.iqa.sets, rid: s => s.id, search: s => s.name + s.by, filters: [{ k: 's', l: 'Status', get: s => s.status, opts: ['Open', 'Finalised', 'Exported'] }, { k: 'p', l: 'Purpose', get: s => s.purpose }, { k: 'b', l: 'Created by', get: s => s.by }],
  cols: [{ k: 'name', l: 'Set', h: s => `<a href="#q-set.${s.id}" data-go="q-set" data-id="${s.id}" class="strong">${esc(s.name)}</a>${S.iqa.cur === s.id ? ' <span class="typebadge">Current</span>' : ''}` }, { k: 'purpose', l: 'Purpose', h: s => `<span class="small">${esc(s.purpose)}</span>` }, { k: 'by', l: 'Created by' }, { k: 'at', l: 'Created', h: s => fd(s.at), s: s => s.at }, { k: 'n', l: 'Items', r: 1, v: s => s.items.length }, { k: 'as', l: 'Assessors', r: 1, v: s => new Set(s.items.map(id => (recById(id) || {}).assessor)).size }, { k: 'un', l: 'Units', r: 1, v: s => new Set(s.items.map(id => (recById(id) || {}).unit)).size }, { k: 'status', l: 'Status', h: s => chip(s.status, S_TONE[s.status]) }, { k: 'exp', l: 'Last export', h: s => s.exports.length ? fd(s.exports[s.exports.length - 1].at) : '—', v: s => s.exports.length }],
  act: s => `<button class="btn btn-sm" data-go="q-set" data-id="${s.id}">Open</button>`, empty: 'No sample sets yet', emptyCta: '<button class="btn btn-primary" data-act="qNewSet">Create your first set</button>' })}`;
SCREENS['q-set'] = (p) => {
  const s = STORE.iqa.sets.find(x => x.id === p.id); if (!s) return notFound();
  const mine = s.by === ADMIN.me.name, recs = s.items.map(recById).filter(Boolean), open = s.status === 'Open' && mine;
  const cnt = key => Object.entries(recs.reduce((m, r) => (m[key(r)] = (m[key(r)] || 0) + 1, m), {})).sort().map(([k, n]) => `<li class="li" style="padding:3px 0"><span style="flex:1">${esc(k)}</span><strong>${n}</strong></li>`).join('');
  return `${pageA(esc(s.name), `${esc(s.purpose)} · created by ${esc(s.by)} · ${fd(s.at)}`, chip(s.status, S_TONE[s.status]), [['Sample Sets', 'q-sets'], [s.name]])}
  ${!mine ? `<div class="note b-grey">${ic('eye')}<div class="small">Created by another IQA — read-only. <button class="linklike" data-act="qDupSet" data-id="${s.id}">Duplicate to my sets</button></div></div>` : ''}${s.status !== 'Open' ? `<div class="note b-grey">${ic('lock')}<div class="small">Set finalised — the item list can't change. Create a new set to sample more.</div></div>` : ''}
  <div class="row">${open ? `<button class="btn" data-act="qUseSet" data-id="${s.id}">${S.iqa.cur === s.id ? 'Current set ✓' : 'Make this my current set'}</button><button class="btn" data-go="q-records">Add items from Assessment Records</button><button class="btn btn-primary" data-act="qFinalise" data-id="${s.id}">Finalise set</button>` : ''}${mine && s.status !== 'Open' ? `<button class="btn btn-primary" data-act="qExport" data-id="${s.id}">${ic('download', 15)}Export set</button>` : ''}${mine && s.status === 'Open' ? `<button class="btn" data-act="qExport" data-id="${s.id}">Export (finalise first)</button>` : ''}</div>
  ${s.note ? `<p class="small"><strong>Note:</strong> ${esc(s.note)}</p>` : ''}
  <div class="q-work"><div class="q-main">${dt({ id: 'qset-' + s.id, name: s.name, rows: recs, rid: r => r.id, cols: [{ k: 'id', l: 'Record', h: r => `<a href="#q-record.${r.id}" data-go="q-record" data-id="${r.id}" class="mono">${r.id}</a>` }, { k: 'learner', l: 'Learner' }, { k: 'assessor', l: 'Assessor' }, { k: 'unit', l: 'Unit' }, { k: 'round', l: 'Round', h: r => `<span class="code">${r.round}</span>` }, { k: 'exit', l: 'Outcome', h: r => `<span class="small">${r.exit}</span>` }, { k: 'fi', l: 'Findings', h: r => recFindings(r).length ? `<span class="iqa-badge sm">${ic('shield', 12)}${recFindings(r).length}</span>` : '', s: r => recFindings(r).length, r: 1 }], act: r => open ? `<button class="btn btn-sm" data-act="qRemove" data-s="${s.id}" data-id="${r.id}">Remove</button>` : '', empty: 'No items yet — add them from Assessment Records' })}</div>
  <aside class="card q-cov"><h2 class="small">Coverage (counts only)</h2><h3 class="small">By assessor</h3><ul class="list xs">${cnt(r => r.assessor)}</ul><h3 class="small">By unit</h3><ul class="list xs">${cnt(r => r.unit)}</ul><h3 class="small">By round</h3><ul class="list xs">${cnt(roundGroup)}</ul><h3 class="small">By type</h3><ul class="list xs">${cnt(r => r.type)}</ul></aside></div>
  <section class="card"><h2>Export history</h2>${s.exports.length ? `<div class="tbl-wrap"><table class="tbl dense"><thead><tr><th>When</th><th>By</th><th>Format</th><th>Findings</th><th>Redacted</th><th>Status</th><th></th></tr></thead><tbody>${s.exports.slice().reverse().map((e, k) => `<tr><td class="small">${fdt(e.at)}</td><td class="small">${esc(e.by)}</td><td class="small">${esc(e.fmt)}</td><td>${e.findings ? 'Yes' : 'No'}</td><td>${e.redact ? 'Yes' : 'No'}</td><td>${chip(e.status, { Ready: 'green', Preparing: 'blue', Failed: 'red' }[e.status])}</td><td>${e.status === 'Ready' ? `<button class="btn btn-sm" data-act="qDl">${ic('download', 14)}Download</button>` : e.status === 'Failed' ? `<button class="btn btn-sm" data-act="qExport" data-id="${s.id}">Retry</button>` : ''}</td></tr>`).join('')}</tbody></table></div>` : '<p class="small muted">Not exported yet.</p>'}</section>${auditPanel(a => a.entity === s.id)}`;
};
ACT.qNewSet = el => openModal({ title: 'Create sample set', body: `<div class="field"><label for="qs-n">Name</label><input class="input" id="qs-n"></div><div class="field"><label for="qs-p">Purpose</label><select class="select" id="qs-p"><option>Internal QA</option><option>Awarding body / EQA visit</option><option>Standardisation</option><option>Other</option></select></div><div class="field"><label for="qs-o">Note (optional)</label><input class="input" id="qs-o" placeholder="e.g. EQA visit 12 Nov 2026"></div>`, actions: [{ label: 'Cancel' }, { label: 'Create set', cls: 'btn-primary', fn: () => { const n = mval('#qs-n'); if (!n) { fieldErr('#qs-n', 'Name the set'); return false; } const s = qCreateSet(n, mval('#qs-p'), mval('#qs-o')); const pend = el && el.dataset && el.dataset.pend; if (pend) { s.items.push(...pend.split(',').filter(x => x && !s.items.includes(x))); iqaLog(s.id, 'Items added', pend.split(',').length + ' items', ''); } render(); toast(`Set "${n}" created${pend ? ' with ' + pend.split(',').length + ' items' : ''} — it's now your current set.`); } }] });
function qCreateSet(name, purpose, note) { const s = { id: 'SS-' + String(STORE.iqa.sets.length + 1).padStart(2, '0'), name, purpose, note, by: ADMIN.me.name, at: now().toISOString(), items: [], status: 'Open', exports: [] }; STORE.iqa.sets.push(s); S.iqa.cur = s.id; iqaLog(s.id, 'Sample set created', name, purpose); return s; }
function qAddToSet(ids) {
  const mineOpen = STORE.iqa.sets.filter(s => s.by === ADMIN.me.name && s.status === 'Open'), cur = STORE.iqa.sets.find(s => s.id === S.iqa.cur);
  if (cur && cur.status !== 'Open') { openModal({ title: 'Set finalised', body: `<div class="note b-amber">${ic('lock')}<div class="small"><strong>Set finalised — create a new set.</strong> "${esc(cur.name)}" can no longer change.</div></div>`, actions: [{ label: 'Close' }, { label: 'Create a new set', cls: 'btn-primary', fn: () => { S.iqa.cur = null; ACT.qNewSet({ dataset: { pend: ids.join(',') } }); } }] }); return; }
  openModal({ title: `Add ${ids.length} item${ids.length > 1 ? 's' : ''} to a sample set`, body: mineOpen.length ? `<fieldset class="stack" style="border:0;padding:0"><legend class="lbl">Choose a set</legend>${mineOpen.map(s => `<label class="check"><input type="radio" name="qa-s" value="${s.id}" ${s.id === S.iqa.cur || (!S.iqa.cur && s === mineOpen[0]) ? 'checked' : ''}>${esc(s.name)} <span class="xs muted">(${s.items.length} items)</span></label>`).join('')}</fieldset>` : '<p class="small">You have no open sets yet.</p>',
    actions: [{ label: 'Cancel' }, { label: 'Create a new set', cls: 'btn', fn: () => { ACT.qNewSet({ dataset: { pend: ids.join(',') } }); } }].concat(mineOpen.length ? [{ label: 'Add to set', cls: 'btn-primary', fn: () => { const s = STORE.iqa.sets.find(x => x.id === ($('#modal-root input[name="qa-s"]:checked') || {}).value); const add = ids.filter(id => !s.items.includes(id)); s.items.push(...add); S.iqa.cur = s.id; iqaLog(s.id, 'Items added', add.length + ' items', ''); if (dts('qrec')) dts('qrec').sel = []; render(); toast(`${add.length} item${add.length === 1 ? '' : 's'} added to "${s.name}"${ids.length - add.length ? ' (' + (ids.length - add.length) + ' already in it)' : ''}.`); } }] : []) });
}
ACT.qAddOne = el => qAddToSet([el.dataset.id]);
ACT.qUseSet = el => { S.iqa.cur = el.dataset.id; render(); toast('Current sample set changed.'); };
ACT.qRemove = el => { const s = STORE.iqa.sets.find(x => x.id === el.dataset.s); confirmDlg({ title: 'Remove from set?', ok: 'Remove', body: `<p class="small">${esc(el.dataset.id)} will be removed from "${esc(s.name)}". The record itself is not changed.</p>`, onOk: () => { s.items = s.items.filter(x => x !== el.dataset.id); iqaLog(s.id, 'Item removed', el.dataset.id, ''); render(); } }); };
ACT.qFinalise = el => { const s = STORE.iqa.sets.find(x => x.id === el.dataset.id); if (!s.items.length) { toast('Add at least one item before finalising.', 'err'); return; } reasonDlg({ title: 'Finalise ' + esc(s.name), ok: 'Finalise set', label: 'Note (required)', body: `<p class="small">The set is locked and its ${s.items.length} items can no longer change. You can still export it.</p>`, onOk: r => { s.status = 'Finalised'; s.finalisedAt = now().toISOString(); if (S.iqa.cur === s.id) S.iqa.cur = null; iqaLog(s.id, 'Sample set finalised', s.items.length + ' items', r); render(); toast('Set finalised.'); } }); };
ACT.qDupSet = el => { const s = STORE.iqa.sets.find(x => x.id === el.dataset.id), n = qCreateSet(s.name + ' (copy)', s.purpose, 'Duplicated from ' + s.id); n.items = s.items.slice(); go('q-set', { id: n.id }); toast('Duplicated to your sets.'); };
ACT.qExport = el => { const s = STORE.iqa.sets.find(x => x.id === el.dataset.id); if (s.status === 'Open') { toast('Finalise the set before exporting it.', 'info'); return; } openModal({ title: 'Export ' + esc(s.name), body: `${s.items.length > 40 ? `<div class="note b-amber">${ic('alert')}<div class="small"><strong>Large set (${s.items.length} items).</strong> The ZIP may take several minutes — we'll notify you.</div></div>` : ''}<fieldset class="stack" style="border:0;padding:0"><legend class="lbl">Format</legend><label class="check"><input type="radio" name="qx-f" value="ZIP of PDFs + CSV index" checked>ZIP of PDFs (each record exactly as on screen — ink colours, RAG, stamps, attribution) + CSV index</label><label class="check"><input type="radio" name="qx-f" value="CSV index only">CSV index only</label></fieldset><label class="check"><input type="checkbox" id="qx-i" checked>Include IQA findings</label><label class="check"><input type="checkbox" id="qx-r">Redact learner personal details</label><p class="xs muted">Every export is logged and visible to the Super Administrator in Audit.</p>`,
  actions: [{ label: 'Cancel' }, { label: 'Start export', cls: 'btn-primary', fn: () => { const e = { at: now().toISOString(), by: ADMIN.me.name, fmt: ($('#modal-root input[name="qx-f"]:checked') || {}).value, findings: $('#qx-i').checked, redact: $('#qx-r').checked, status: 'Preparing' }; s.exports.push(e); s.status = s.status === 'Finalised' ? 'Exported' : s.status; ADMIN.exportsLog.unshift({ who: ADMIN.me.name, what: `IQA sample set ${s.id} (${e.fmt}${e.redact ? ', redacted' : ''}${e.findings ? ', with findings' : ''})`, at: e.at }); logA('Audit & Security Logs', s.id, 'IQA sample set exported', '—', e.fmt, `Findings: ${e.findings ? 'yes' : 'no'} · redacted: ${e.redact ? 'yes' : 'no'}`); iqaLog(s.id, 'Export started', e.fmt, ''); render(); toast('Preparing export — export logged. We\'ll notify you when it\'s ready.', 'info');
    setTimeout(() => { const fail = STORE.iqa.failNext; STORE.iqa.failNext = false; e.status = fail ? 'Failed' : 'Ready'; iqaNotify(fail ? 'Export failed' : 'Export ready', `${s.id} · ${e.fmt}${fail ? ' — retry from the set' : ''}`, 'q-set.' + s.id, ADMIN.me.name); if (S.portal === 'admin') render(); toast(fail ? 'Export failed — retry from the set.' : 'Export ready — download from the set or notifications.', fail ? 'err' : 'ok'); }, 1500); } }] }); };
