SCREENS.index = p => _idxQ(p) + `<section class="card idx-sec"><h2>IQA</h2><ul class="idx-list"><li><button class="linklike" data-act="demoSignInAsIqa" data-v="QA">Sign in as IQA A (demo) — no 2FA</button></li><li><button class="linklike" data-act="demoSignInAsIqa" data-v="QB">Sign in as IQA B (demo) — no 2FA</button></li><li><button class="linklike" data-act="demoSignInAsIqa" data-v="QC">Variant C — IQA + Assessor (conflict of interest)</button></li></ul></section>`;
