/* G6.9: the IQA closes a finding once the marking Assessor has acknowledged it */
const _qFindingClose = SCREENS['q-finding'];
SCREENS['q-finding'] = (p) => { const h = _qFindingClose(p), f = ADMIN.iqa.find(x => x.id === p.id); if (!f) return h; const st = f.status || 'Open';
  return h + `<section class="card"><h2>Status</h2><p>${chip(st, { Open: 'amber', Acknowledged: 'blue', Closed: 'grey' }[st])} ${st === 'Open' ? 'Waiting for the marking Assessor to acknowledge.' : st === 'Acknowledged' ? `Acknowledged by ${esc((f.ack || {}).by || f.assessor)}${f.ack ? ' · ' + fd(f.ack.at) + ' — ' + esc(f.ack.note) : ''}.` : 'Closed.'}</p>${(f.notes || []).map(n => `<p class="xs muted">${esc(n[0])} · ${fd(n[1])}</p>`).join('')}${st === 'Acknowledged' && isIqa() ? `<button class="btn btn-primary" data-act="qClose" data-id="${f.id}">Close finding</button>` : ''}<p class="xs muted">Open → Acknowledged (by the Assessor who marked the work) → Closed (by the IQA).</p></section>`; };
